/**
 * Returns the sessions of the current project's machines, newest first. Closed sessions are
 * omitted unless `include_closed` is true.
 * @summary List sessions
 */
export const listSessionsQueryPageDefault = 1;
export const listSessionsQueryPageMax = 2147483647;

export const listSessionsQueryPageSizeDefault = 50;
export const listSessionsQueryPageSizeMax = 200;

export const listSessionsQueryIncludeClosedDefault = false;

export const ListSessionsQueryParams = zod.strictObject({
  page: zod
    .int()
    .min(1)
    .max(listSessionsQueryPageMax)
    .default(listSessionsQueryPageDefault)
    .describe("1-based page number. Defaults to 1."),
  page_size: zod
    .int()
    .min(1)
    .max(listSessionsQueryPageSizeMax)
    .default(listSessionsQueryPageSizeDefault)
    .describe("Items per page. Defaults to 50; at most 200."),
  machine_id: zod.uuid().optional().describe("Return only the sessions of this machine"),
  user_id: zod.uuid().optional().describe("Return only the sessions of this member"),
  include_closed: zod
    .boolean()
    .default(listSessionsQueryIncludeClosedDefault)
    .describe("Include closed sessions; defaults to false"),
});

/**
 * Opens a session for the caller on a machine, as the caller's account, and returns once it
 * is ready. With `desktop` the session has a desktop. Without, it is a terminal session: its
 * one terminal runs the caller's login shell from the start, every participant attaches to
 * that terminal, and the session ends when the shell exits; a caller who wants another
 * terminal opens another session. Either kind also offers programs, files, ports, sound,
 * devices, printers and privilege approvals. The account is created if the caller has none
 * yet. Requires `fleet:machines.login` on the machine.
 *
 * On a machine an account has at most one session with a desktop and at most 8 sessions in
 * all. Sessions without a desktop run side by side, such as one for a program and one for a
 * person; several participants can also share one session.
 *
 * Fails with:
 * - `MACHINE_OFFLINE` when the machine is not connected and does not connect again in time;
 * - `FEATURE_UNAVAILABLE` when the machine does not offer sessions, or with `desktop`,
 *   desktops;
 * - `USER_HAS_DESKTOP_SESSION` with `desktop` when the account already has a session with a
 *   desktop on the machine, which `metadata.sessionId` names; connect to it instead;
 * - `SESSION_LIMIT_REACHED` when the account already has 8 open sessions on the machine;
 *   close one first;
 * - `USER_NOT_FOUND`, `USER_NOT_ALLOWED`, `ACCOUNT_EXPIRED` or `PAM_PERMISSION_DENIED` when
 *   the machine refuses the account, such as while it has not received the account yet or a
 *   local account uses its name; `PAM_PERMISSION_DENIED` carries the machine's message in
 *   `metadata.pamMessage`;
 * - `SESSION_CONFLICT` with `desktop` when the account has a graphical session on the
 *   machine that Fleet did not open;
 * - `DISPLAY_UNAVAILABLE` or `SESSION_START_FAILED` when the machine could not start it;
 * - `MACHINE_TIMEOUT` when the machine did not answer in time. The session may still open;
 *   list the sessions before trying again.
 * @summary Open a session
 */
export const CreateSessionBody = CreateSessionRequest;

/**
 * @summary Get a session
 */
export const getSessionPathSessionIdMax = 40;

export const getSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const GetSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(getSessionPathSessionIdMax)
    .regex(getSessionPathSessionIdRegExp),
});

/**
 * Ends the session in order: its applications are asked to exit and get a grace period
 * before the session is terminated. Returns once the session is closed. Closing a closed
 * session succeeds.
 *
 * The owner may close their own session; closing another member's requires
 * `fleet:sessions.manage`. Fails with `MACHINE_OFFLINE` or `MACHINE_TIMEOUT` as
 * for opening a session.
 * @summary Close a session
 */
export const closeSessionPathSessionIdMax = 40;

export const closeSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CloseSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(closeSessionPathSessionIdMax)
    .regex(closeSessionPathSessionIdRegExp),
});

/**
 * Ends the session at once, killing every process in it. Returns once the session is
 * closed. Terminating a closed session succeeds.
 *
 * The owner may terminate their own session; terminating another member's requires
 * `fleet:sessions.manage`. Fails with `MACHINE_OFFLINE` or `MACHINE_TIMEOUT` as
 * for opening a session.
 * @summary Terminate a session
 */
export const terminateSessionPathSessionIdMax = 40;

export const terminateSessionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const TerminateSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(terminateSessionPathSessionIdMax)
    .regex(terminateSessionPathSessionIdRegExp),
});

/**
 * Returns the STUN and TURN servers for the PeerConnections the caller starts to the session,
 * with TURN credentials of its own, and the policy for using them. Ask again once
 * `expires_at` has passed; the credentials of a PeerConnection already relayed last longer.
 *
 * Requires that the caller may join the session, as for `create-participant`.
 *
 * Fails with:
 * - `SESSION_CLOSED` when the session has ended;
 * - `SESSION_ACCESS_DENIED` when the caller may not join the session.
 * @summary Get the ICE servers for a session
 */
export const getSessionRtcConfigurationPathSessionIdMax = 40;

export const getSessionRtcConfigurationPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const GetSessionRtcConfigurationParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(getSessionRtcConfigurationPathSessionIdMax)
    .regex(getSessionRtcConfigurationPathSessionIdRegExp),
});

/**
 * Admits one participant with the given public key to the session: signs its authorization,
 * has the session accept it, and starts its first PeerConnection with the offer. The answer
 * carries the participant, its authorization and the PeerConnection with the session's
 * answer. The participant lasts while it is renewed.
 *
 * Joining again with the public key of one of the caller's participants of the session that
 * has not ended, with the same `client_name`, `read_only` and `permissions`, returns that
 * participant with a new PeerConnection for the offer, and the session gains no second
 * participant: a request whose answer was lost, such as on an unreliable network, is sent
 * again as it was. Its earlier PeerConnection, whose answer the client never received, is
 * given up by the session once it fails.
 *
 * The owner of a session may operate it. Joining another member's session requires
 * `fleet:sessions.view`, which admits watching only, or
 * `fleet:sessions.control`, which also admits operating it. Each further capability
 * of the session — file transfer, the clipboard, terminals and programs, port forwarding,
 * devices and audio, printing, SSH agent forwarding, approving privilege requests and
 * reading logs — is granted only with its permission; a participant that may only watch gets
 * none of them. A request may ask for less: to watch only, or for some of the capabilities.
 *
 * Fails with the following, and then no participant was created:
 * - `SESSION_CLOSED` when the session has ended;
 * - `SESSION_ACCESS_DENIED` when the caller may not join the session;
 * - `OFFER_INVALID` when the offer is not an SDP offer that names a SHA-256 DTLS fingerprint;
 * - `SESSION_UNAVAILABLE` when the session's process is not connected and does not connect
 *   again in time, or did not answer in time; try again after the error's `retry_delay`;
 * - `PARTICIPANT_LIMIT_REACHED` when the session has as many participants as it admits;
 * - `PARTICIPANT_REFUSED` when the session refused the participant;
 * - `PARTICIPANT_KEY_IN_USE` when the public key belongs to a participant of the session that
 *   another user holds, or that was created with another `client_name`, `read_only` or
 *   `permissions`; join with a new key;
 * - `PEER_CONNECTION_ABORTED` when the session gave up the PeerConnection; try again with a
 *   new offer. The participant of a repeated request stays.
 * @summary Join a session
 */
export const createParticipantPathSessionIdMax = 40;

export const createParticipantPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CreateParticipantParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(createParticipantPathSessionIdMax)
    .regex(createParticipantPathSessionIdRegExp),
});

export const CreateParticipantBody = CreateParticipantRequest;

/**
 * Returns the participants of the session, in the order they joined.
 * @summary List the participants of a session
 */
export const listSessionParticipantsPathSessionIdMax = 40;

export const listSessionParticipantsPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const ListSessionParticipantsParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(listSessionParticipantsPathSessionIdMax)
    .regex(listSessionParticipantsPathSessionIdRegExp),
});

/**
 * Extends the participant's lease and returns renewed PeerAuthorizations for the
 * PeerConnections whose current ones the request presents. The service sends them to the
 * session as well, and the participant passes each one to the session over its PeerConnection
 * (`Packet.peer_authorization` of the transport protocol), so that the lease holds while
 * either path to the session is down. A
 * presented authorization that the service did not sign for this participant, or whose
 * PeerConnection has ended, is left out of the answer. When the participant's authorization
 * nears its end, the answer carries a renewed one, which the session already holds.
 *
 * Only the participant's user may renew it.
 *
 * Fails with:
 * - `PARTICIPANT_NOT_FOUND` when the participant has ended; create another;
 * - `PARTICIPANT_RIGHTS_CHANGED` when the caller's permissions no longer grant what the
 *   participant holds; it has ended, and another can be created with the current rights.
 * @summary Renew a participant
 */
export const renewParticipantPathSessionIdMax = 40;

export const renewParticipantPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const RenewParticipantParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(renewParticipantPathSessionIdMax)
    .regex(renewParticipantPathSessionIdRegExp),
  participantId: zod.int().min(1),
});

export const RenewParticipantBody = RenewParticipantRequest;

/**
 * Passes the participant's checkpoint for the next epoch to the session and returns the
 * session's checkpoint for it: the `prepare` and `prepared` steps of `Migration` in
 * `leaflow/fleet/transport/v1/transport.proto`. Repeating the step returns the same answer.
 *
 * Only the participant's user may migrate it.
 *
 * Fails with:
 * - `PARTICIPANT_NOT_FOUND` when the participant has ended;
 * - `CHECKPOINT_INVALID` when the checkpoint is not a serialized `Checkpoint`;
 * - `SESSION_UNAVAILABLE` when the session's process is not connected and does not connect
 *   again in time, or did not answer in time; try again after the error's `retry_delay`.
 * @summary Prepare a migration
 */
export const prepareParticipantMigrationPathSessionIdMax = 40;

export const prepareParticipantMigrationPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const PrepareParticipantMigrationParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(prepareParticipantMigrationPathSessionIdMax)
    .regex(prepareParticipantMigrationPathSessionIdRegExp),
  participantId: zod.int().min(1),
});

export const PrepareParticipantMigrationBody = MigrationStep;

/**
 * Commits the epoch the participant prepared and returns the session's checkpoint once it
 * committed it: the `commit` and `committed` steps of `Migration` in
 * `leaflow/fleet/transport/v1/transport.proto`. Repeating the step returns the same answer.
 *
 * Only the participant's user may migrate it.
 *
 * Fails with:
 * - `PARTICIPANT_NOT_FOUND` when the participant has ended;
 * - `CHECKPOINT_INVALID` when the checkpoint is not a serialized `Checkpoint`;
 * - `SESSION_UNAVAILABLE` when the session's process is not connected and does not connect
 *   again in time, or did not answer in time; try again after the error's `retry_delay`.
 * @summary Commit a migration
 */
export const commitParticipantMigrationPathSessionIdMax = 40;

export const commitParticipantMigrationPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CommitParticipantMigrationParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(commitParticipantMigrationPathSessionIdMax)
    .regex(commitParticipantMigrationPathSessionIdRegExp),
  participantId: zod.int().min(1),
});

export const CommitParticipantMigrationBody = MigrationStep;

/**
 * Starts another PeerConnection of the participant with the offer, such as after a path
 * failed, and returns the session's answer, its ICE candidates and the signed
 * PeerAuthorization. Move the participant's connection to it with
 * `prepare-participant-migration` and `commit-participant-migration`.
 *
 * Only the participant's user may start one.
 *
 * Fails with:
 * - `PARTICIPANT_NOT_FOUND` when the participant has ended;
 * - `OFFER_INVALID` when the offer is not an SDP offer that names a SHA-256 DTLS fingerprint;
 * - `RATE_LIMIT_EXCEEDED` when the participant started too many PeerConnections in the
 *   last minute; try again after the error's `retry_delay`;
 * - `SESSION_UNAVAILABLE` when the session's process is not connected and does not connect
 *   again in time, or did not answer in time; try again after the error's `retry_delay`;
 * - `PEER_CONNECTION_ABORTED` when the session gave up the PeerConnection; start another.
 * @summary Start a PeerConnection
 */
export const createPeerConnectionPathSessionIdMax = 40;

export const createPeerConnectionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CreatePeerConnectionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(createPeerConnectionPathSessionIdMax)
    .regex(createPeerConnectionPathSessionIdRegExp),
  participantId: zod.int().min(1),
});

export const CreatePeerConnectionBody = CreatePeerConnectionRequest;

/**
 * Tells the session to give up the PeerConnection and close it. Abandoning a PeerConnection
 * that has ended succeeds.
 *
 * Only the participant's user may abandon it.
 *
 * Fails with `PARTICIPANT_NOT_FOUND` when the participant has ended.
 * @summary Abandon a PeerConnection
 */
export const deletePeerConnectionPathSessionIdMax = 40;

export const deletePeerConnectionPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const DeletePeerConnectionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(deletePeerConnectionPathSessionIdMax)
    .regex(deletePeerConnectionPathSessionIdRegExp),
  participantId: zod.int().min(1),
  peerConnectionId: zod.uuid(),
});

/**
 * Passes the ICE candidates the participant gathered after its offer to the session, and with
 * `end_of_candidates`, that it has gathered all (RFC 8838). The session ignores those of a
 * PeerConnection that has ended.
 *
 * Only the participant's user may add them.
 *
 * Fails with:
 * - `PARTICIPANT_NOT_FOUND` when the participant has ended;
 * - `SESSION_UNAVAILABLE` when the session's process is not connected and does not connect
 *   again in time; try again after the error's `retry_delay`.
 * @summary Add ICE candidates to a PeerConnection
 */
export const createPeerConnectionCandidatesPathSessionIdMax = 40;

export const createPeerConnectionCandidatesPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const CreatePeerConnectionCandidatesParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(createPeerConnectionCandidatesPathSessionIdMax)
    .regex(createPeerConnectionCandidatesPathSessionIdRegExp),
  participantId: zod.int().min(1),
  peerConnectionId: zod.uuid(),
});

export const CreatePeerConnectionCandidatesBody = CreatePeerConnectionCandidatesRequest;

/**
 * Returns a participant of the session.
 * @summary Get a participant of a session
 */
export const getParticipantPathSessionIdMax = 40;

export const getParticipantPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const GetParticipantParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(getParticipantPathSessionIdMax)
    .regex(getParticipantPathSessionIdRegExp),
  participantId: zod.int().min(1),
});

/**
 * Ends the participant: the session detaches it and closes its PeerConnections, and the
 * session goes on. A participant leaves this way; others are disconnected this way.
 *
 * The participant's user and the owner of the session may end it; otherwise this
 * requires `fleet:sessions.manage`.
 * @summary End a participant
 */
export const deleteParticipantPathSessionIdMax = 40;

export const deleteParticipantPathSessionIdRegExp = new RegExp("^[a-z0-9-]+$");

export const DeleteParticipantParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(1)
    .max(deleteParticipantPathSessionIdMax)
    .regex(deleteParticipantPathSessionIdRegExp),
  participantId: zod.int().min(1),
});
